const String presentFragSrc = '''
#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uTex;
uniform float uExposure;
uniform float uVignette;
uniform float uGrain;
uniform float uOutputEncoding;
uniform float uToneMap;
out vec4 oColor;

float hash(vec2 p){
  return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);
}

vec3 reinhardToneMap(vec3 color){
  return color/(vec3(1.)+color);
}

vec3 linearToSrgb(vec3 color){
  vec3 cutoff=step(vec3(.0031308),color);
  vec3 low=color*12.92;
  vec3 high=1.055*pow(max(color,vec3(0.)),vec3(1./2.4))-.055;
  return mix(low,high,cutoff);
}

void main(){
  vec4 source=texture(uTex,vUv);
  // Exposure operates in scene-linear space; tone mapping prevents HDR
  // highlights from clipping before the selected output transfer function.
  vec3 color=max(source.rgb,vec3(0.))*max(uExposure,0.);
  color=mix(color,reinhardToneMap(color),clamp(uToneMap,0.,1.));
  float edge=distance(vUv,vec2(.5));
  float vignette=smoothstep(.35,.78,edge);
  color*=1.-clamp(uVignette,0.,1.)*vignette;
  if(uOutputEncoding>.5) color=linearToSrgb(max(color,vec3(0.)));
  // Atmospheric precipitation is submitted as depth-tested world geometry;
  // the present pass must never paint weather over unrelated surfaces.
  // A stable screen-space grain keeps captures reproducible for a fixed
  // viewport while still giving the dark gothic presentation a fine film
  // texture. It is deliberately tiny and never changes alpha.
  color+=((hash(gl_FragCoord.xy)-.5)*.06)*max(uGrain,0.);
  oColor=vec4(clamp(color,0.,1.),source.a);
}
''';

const String depthPrepassVertSrc = '''
#version 300 es
layout(location=0) in vec3 aPosition;
layout(location=4) in vec3 aUvMat;
uniform mat4 uViewProjection;
uniform mat4 uModel;
uniform mat4 uInstanceModels[16];
uniform float uUseInstances;
uniform float uVertexSnapGrid;
uniform float uAffineWarpStrength;
out highp vec2 vUv;
out highp float vUvW;
// This prepass must land geometry on exactly the same pixels shadowedWorld
// will, because its depth is what SSAO occludes against and what
// shadowedWorld then samples back at its *own* gl_FragCoord. Snapping there
// and not here would mean the AO texel a fragment reads was computed for a
// slightly different surface than the one being shaded, and the error grows
// with the grid. The snap math below is deliberately identical to
// shadowed_world.vert's, including uVertexSnapGrid==0 skipping the branch.
// The same reasoning now covers UVs: an alpha-masked surface's holes must
// land on the same pixels in both passes, and affine sampling moves where a
// given texel lands, so the w-premultiply below is the same expression
// shadowed_world.vert uses and is driven from the same per-material weight.
void main(){
  mat4 model=uModel;
  if(uUseInstances>0.5){model=uInstanceModels[gl_InstanceID];}
  vec4 clip=uViewProjection*model*vec4(aPosition,1.0);
  if(uVertexSnapGrid>0.0){
    vec2 ndc=clip.xy/clip.w;
    ndc=floor(ndc/uVertexSnapGrid+0.5)*uVertexSnapGrid;
    clip.xy=ndc*clip.w;
  }
  gl_Position=clip;
  float affineW=mix(1.0,clip.w,uAffineWarpStrength);
  vUv=aUvMat.xy*affineW;
  vUvW=affineW;
}
''';

const String depthPrepassFragSrc = '''
#version 300 es
precision highp float;
in highp vec2 vUv;
in highp float vUvW;
uniform sampler2D uAlbedo;
uniform float uAlphaCutoff;
uniform float uAffineWarpStrength;
// §6.2: "includes opaque + alpha-masked depth." A masked surface's holes
// must not write depth, or SSAO occludes against geometry the world pass
// discarded and DOF's CoC defocuses against a surface nothing shaded. The
// compare is bit-identical to shadowed_world.frag's — same uv recovery,
// same threshold, same direction — because any divergence reintroduces
// exactly the class of bug the vertex-snap parity fix (bug 17) closed.
// Everything is inside the uAlphaCutoff>0. branch, so an unmasked draw
// costs no texture fetch at all here, only the interpolation the varyings
// were already going to do.
void main(){
  if(uAlphaCutoff>0.){
    vec2 uv=uAffineWarpStrength>0.?vUv/vUvW:vUv;
    if(texture(uAlbedo,uv).a<uAlphaCutoff)discard;
  }
}
''';

const String depthDebugFragSrc = '''
#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uSceneDepth;
uniform float uNear;
uniform float uFar;
uniform float uDisplayRange;
out vec4 oColor;
void main(){
  float raw=texture(uSceneDepth,vUv).r;
  float ndc=raw*2.0-1.0;
  float linear=(2.0*uNear*uFar)/(uFar+uNear-ndc*(uFar-uNear));
  // uFar is the camera's real projection far plane (100, for correct depth
  // reconstruction above) — normalizing display shade against it directly
  // would crush every visible surface (a handful of units away) into a
  // sliver near 0.0, indistinguishable from black, while the empty
  // background (which clears to exactly uFar) reads pure white. uDisplayRange
  // is a separate, much smaller distance chosen to match this scene's
  // actual scale, so nearby geometry spans a real visible gradient instead
  // of a hard silhouette.
  float shade=clamp(linear/uDisplayRange,0.0,1.0);
  oColor=vec4(vec3(shade),1.0);
}
''';

const String ssaoOcclusionFragSrc = '''
#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uSceneDepth;
uniform float uNear;
uniform float uFar;
uniform float uProjScaleX;
uniform float uProjScaleY;
uniform float uRadius;
uniform float uStrength;
out vec4 oColor;

const int KERNEL_SIZE=8;
const vec3 KERNEL[8]=vec3[8](
  vec3( 0.35, 0.23, 0.45),
  vec3(-0.28, 0.41, 0.32),
  vec3( 0.18,-0.36, 0.55),
  vec3(-0.42,-0.19, 0.28),
  vec3( 0.51, 0.08, 0.18),
  vec3(-0.11, 0.53, 0.16),
  vec3( 0.07,-0.48, 0.38),
  vec3(-0.33,-0.31, 0.48)
);

float linearDepth(float raw){
  float ndc=raw*2.0-1.0;
  return (2.0*uNear*uFar)/(uFar+uNear-ndc*(uFar-uNear));
}

vec3 viewPosAt(vec2 uv){
  float viewZ=-linearDepth(texture(uSceneDepth,uv).r);
  vec2 ndc=uv*2.0-1.0;
  float viewX=ndc.x*(-viewZ)/uProjScaleX;
  float viewY=ndc.y*(-viewZ)/uProjScaleY;
  return vec3(viewX,viewY,viewZ);
}

// Pinned per-pixel kernel rotation — a deterministic hash of screen
// position, not per-frame randomness, matching §8.5's "rotates a small
// kernel from pinned blue noise" without the extra machinery of an actual
// noise texture: the rotation angle is stable across frames for a given
// pixel, which is what "pinned" requires (temporal stability), while still
// varying spatially enough to break up banding between neighboring samples.
float pinnedRotation(vec2 fragCoord){
  return fract(sin(dot(fragCoord,vec2(12.9898,78.233)))*43758.5453)*6.2831853;
}

void main(){
  vec3 originView=viewPosAt(vUv);
  // Screen-space derivatives reconstruct a per-fragment normal from
  // neighboring depth samples alone — no G-buffer normal attachment exists
  // (deferred; see depth_prepass.dart's doc comment), which is sufficient
  // for a chunky/stylized AO term rather than a precision-critical one.
  vec3 normalView=normalize(cross(dFdx(originView),dFdy(originView)));

  // Rotates each kernel sample's tangent-plane (x,y) offset in place, before
  // it's transformed into view space by tbn below — this is what actually
  // varies the kernel per pixel; rotating the already-reprojected screen UV
  // afterward would rotate around the wrong origin and misalign every
  // sample from the surface it's meant to test.
  float angle=pinnedRotation(gl_FragCoord.xy);
  float ca=cos(angle);
  float sa=sin(angle);
  mat2 rot=mat2(ca,sa,-sa,ca);

  vec3 up=abs(normalView.z)<0.99?vec3(0.0,0.0,1.0):vec3(1.0,0.0,0.0);
  vec3 tangent=normalize(cross(up,normalView));
  vec3 bitangent=cross(normalView,tangent);
  mat3 tbn=mat3(tangent,bitangent,normalView);

  float occlusion=0.0;
  for(int i=0;i<KERNEL_SIZE;i++){
    vec3 kernelSample=KERNEL[i];
    kernelSample.xy=rot*kernelSample.xy;
    vec3 samplePos=originView+tbn*kernelSample*uRadius;
    // Project the sample's view-space position back to screen UV using the
    // same scale factors used to reconstruct it, inverted.
    vec2 sampleUv=vec2(
      samplePos.x*uProjScaleX/(-samplePos.z),
      samplePos.y*uProjScaleY/(-samplePos.z)
    );
    // NDC [-1,1] -> UV [0,1] requires the constant 0.5, not vUv (the
    // *current* fragment's own UV) — adding vUv here was a real bug: it
    // conflated "this sample's own absolute reprojected screen position"
    // with "an offset relative to the current fragment," producing an
    // error of (vUv-0.5) per axis that grows with distance from screen
    // center. That's exactly what produced a huge, blobby, non-local dark
    // region instead of contact occlusion — every sample tested a wildly
    // wrong depth location except right at screen center, where the error
    // happened to be near zero.
    sampleUv=sampleUv*0.5+0.5;
    if(sampleUv.x<0.0||sampleUv.x>1.0||sampleUv.y<0.0||sampleUv.y>1.0){
      continue;
    }
    vec3 occluderView=viewPosAt(sampleUv);
    float rangeCheck=smoothstep(0.0,1.0,uRadius/max(abs(originView.z-occluderView.z),0.0001));
    occlusion+=(occluderView.z>=samplePos.z+0.02?1.0:0.0)*rangeCheck;
  }
  float ao=1.0-clamp((occlusion/float(KERNEL_SIZE))*uStrength,0.0,1.0);
  oColor=vec4(vec3(ao),1.0);
}
''';

const String ssaoBlurFragSrc = '''
#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uSsaoRaw;
uniform sampler2D uSceneDepth;
uniform vec2 uTexelSize;
uniform float uNear;
uniform float uFar;
out vec4 oColor;

float linearDepth(float raw){
  float ndc=raw*2.0-1.0;
  return (2.0*uNear*uFar)/(uFar+uNear-ndc*(uFar-uNear));
}

// §8.5: "uses a depth-aware bilateral blur rather than smearing across
// silhouettes" — a plain box blur would bleed occlusion from a near object
// onto a far background behind it (or vice versa) whenever they share
// screen-space pixels near a silhouette edge; weighting each tap by how
// close its depth is to the center tap's depth is what keeps the blur
// confined to one surface at a time.
void main(){
  float centerDepth=linearDepth(texture(uSceneDepth,vUv).r);
  float sum=0.0;
  float weightSum=0.0;
  for(int y=-2;y<=2;y++){
    for(int x=-2;x<=2;x++){
      vec2 offset=vec2(float(x),float(y))*uTexelSize;
      vec2 sampleUv=vUv+offset;
      float sampleDepth=linearDepth(texture(uSceneDepth,sampleUv).r);
      float depthWeight=1.0/(1.0+abs(sampleDepth-centerDepth)*4.0);
      sum+=texture(uSsaoRaw,sampleUv).r*depthWeight;
      weightSum+=depthWeight;
    }
  }
  float blurred=sum/max(weightSum,0.0001);
  oColor=vec4(vec3(blurred),1.0);
}
''';

