const String dofCompositeFragSrc = '''
#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uSharp;
uniform sampler2D uBlurred;
uniform sampler2D uSceneDepth;
uniform float uNear;
uniform float uFar;
uniform float uFocusDistance;
uniform float uFocusRange;
uniform float uStrength;
out vec4 oColor;

float linearDepth(float raw){
  float ndc=raw*2.0-1.0;
  return (2.0*uNear*uFar)/(uFar+uNear-ndc*(uFar-uNear));
}

// Circle-of-confusion is a simple linear ramp from the focus distance
// outward (front and back treated the same — no separate near/far falloff
// curve), clamped to [0,1] and scaled by uStrength so
// PostProcessState.depthOfFieldStrength == 0 is a true no-op (coc == 0
// everywhere, oColor == the sharp source exactly).
void main(){
  float depth=linearDepth(texture(uSceneDepth,vUv).r);
  float coc=clamp(abs(depth-uFocusDistance)/max(uFocusRange,0.0001),0.0,1.0)*uStrength;
  vec3 sharp=texture(uSharp,vUv).rgb;
  vec3 blurred=texture(uBlurred,vUv).rgb;
  oColor=vec4(mix(sharp,blurred,coc),1.0);
}
''';

const String gradeLutFragSrc = '''
#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uScene;
uniform sampler2D uLut;
uniform float uLutSize;
uniform float uStrength;
out vec4 oColor;

// §5.3's "identity LUT" baseline resource and this shader's actual grade LUT
// are both just textures in this same unwrapped-3D-LUT layout (width =
// size*size, height = size, blue index selects a size*size horizontal
// slice) — there is nothing identity-specific about the sampling path
// itself, only about what a given LUT texture's texels happen to encode.
vec3 sampleLut(vec3 color){
  float size=uLutSize;
  float maxIndex=size-1.0;
  vec3 scaled=clamp(color,0.0,1.0)*maxIndex;
  float bLow=floor(scaled.b);
  float bHigh=min(bLow+1.0,maxIndex);
  float bFrac=scaled.b-bLow;
  vec2 texel=vec2(1.0/(size*size),1.0/size);
  vec2 rg=vec2(scaled.r+0.5,scaled.g+0.5);
  vec2 uvLow=vec2((bLow*size+rg.x)*texel.x,rg.y*texel.y);
  vec2 uvHigh=vec2((bHigh*size+rg.x)*texel.x,rg.y*texel.y);
  vec3 colorLow=texture(uLut,uvLow).rgb;
  vec3 colorHigh=texture(uLut,uvHigh).rgb;
  return mix(colorLow,colorHigh,bFrac);
}

void main(){
  vec3 scene=texture(uScene,vUv).rgb;
  vec3 graded=sampleLut(scene);
  oColor=vec4(mix(scene,graded,uStrength),1.0);
}
''';

const String ps1QuantizeFragSrc = '''
#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uScene;
uniform float uQuantizationBits;
uniform float uDitherStrength;
out vec4 oColor;

const float BAYER4X4[16]=float[16](
  0.0,8.0,2.0,10.0,
  12.0,4.0,14.0,6.0,
  3.0,11.0,1.0,9.0,
  15.0,7.0,13.0,5.0
);

float bayerValue(vec2 fragCoord){
  int x=int(mod(fragCoord.x,4.0));
  int y=int(mod(fragCoord.y,4.0));
  return BAYER4X4[y*4+x]/16.0;
}

// §6.2's "quantization/dither is an explicit composite after LUT grade":
// an ordered (Bayer 4x4) dither offset, scaled to one quantization step, is
// added before rounding to uQuantizationBits levels per channel — this is
// what breaks a hard quantization boundary into a dithered gradient instead
// of a flat color band. uQuantizationBits==8 (RGBA8's own native precision)
// with uDitherStrength==0 round-trips the source exactly: no dither offset
// is added, and floor(x*255+0.5)/255 returns an already-8-bit value
// unchanged.
void main(){
  vec3 scene=texture(uScene,vUv).rgb;
  float levels=pow(2.0,uQuantizationBits)-1.0;
  float dither=(bayerValue(gl_FragCoord.xy)-0.5)*uDitherStrength/levels;
  vec3 dithered=clamp(scene+dither,0.0,1.0);
  vec3 quantized=floor(dithered*levels+0.5)/levels;
  oColor=vec4(quantized,1.0);
}
''';

const String vhsFragSrc = '''
#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uScene;
uniform sampler2D uHistory;
uniform float uTime;
uniform float uChromaWeight;
uniform float uTrackingWeight;
uniform float uNoiseWeight;
uniform float uHeadSwitchWeight;
uniform float uDropoutWeight;
uniform float uGhostWeight;
out vec4 oColor;

float hash(vec2 p){
  return fract(sin(dot(p,vec2(12.9898,78.233)))*43758.5453);
}

// §8.10: "sample the jittered/tracking UV before YIQ/chroma work so later
// sampling does not overwrite earlier effects" — tracking jitter is
// computed and applied to the UV exactly once, up front; every later
// effect either operates on the resulting single sample or samples a
// further offset FROM that same jittered UV, never re-reading uScene at
// the original vUv.
void main(){
  float scanline=vUv.y;

  // Tracking: a per-scanline horizontal jitter, re-rolled roughly 8 times
  // a second (not per-frame) so it reads as tape wobble rather than
  // high-frequency noise. Comfort clamp: 0.02 UV (a few source texels at
  // this bootstrap's 384-wide internal resolution) is the max displacement
  // regardless of weight — a weight of 1.0 must read as "visibly glitchy,"
  // never as "the image is unreadable."
  float trackingNoise=hash(vec2(floor(scanline*216.0),floor(uTime*8.0)))-0.5;
  float jitter=trackingNoise*0.02*uTrackingWeight;
  vec2 uv=vec2(clamp(vUv.x+jitter,0.0,1.0),vUv.y);
  vec3 raw=texture(uScene,uv).rgb;

  // Chroma bleed: convert to YIQ, sample a second, further-offset UV for
  // the chroma (I/Q) channels only — luma (what reads as "sharp" to the
  // eye) stays exactly where tracking already put it; only color smears.
  vec2 chromaUv=vec2(clamp(uv.x+0.01*uChromaWeight,0.0,1.0),uv.y);
  vec3 rawChroma=texture(uScene,chromaUv).rgb;
  float y=dot(raw,vec3(0.299,0.587,0.114));
  float i=dot(rawChroma,vec3(0.596,-0.274,-0.322));
  float q=dot(rawChroma,vec3(0.211,-0.523,0.312));
  vec3 yiqColor=vec3(
    y+0.956*i+0.621*q,
    y-0.272*i-0.647*q,
    y-1.106*i+1.703*q
  );
  vec3 color=mix(raw,yiqColor,uChromaWeight);

  // Static/snow: modeled in YIQ (luma + chroma), the same conversion
  // chroma bleed already uses above, not independent RGB — real analog
  // colour noise comes from the chroma subcarrier, so its hues are
  // correlated/limited rather than arbitrary per-channel static. Noise
  // cells are quantized coarser along x than y, giving each speckle a
  // short horizontal dash instead of an isolated dot — a "vague line
  // shape," matching how scanline-based static actually streaks. A
  // sparser, stronger sparkle layer and a rare single-sample micro-
  // distortion (an actual tiny position offset, not just colour) are both
  // gated by a high-threshold mask so only occasional pixels carry the
  // effect — small magnitude on top of that sparsity, for a sprinkle, not
  // a wash.
  vec2 noiseCell=vec2(floor(gl_FragCoord.x/3.0),gl_FragCoord.y)+uTime*60.0;
  float noiseY=(hash(noiseCell)-0.5)*0.05;
  float noiseI=(hash(noiseCell+vec2(17.0,3.0))-0.5)*0.14;
  float noiseQ=(hash(noiseCell+vec2(53.0,29.0))-0.5)*0.14;
  vec3 noiseYiq=vec3(
    noiseY+0.956*noiseI+0.621*noiseQ,
    noiseY-0.272*noiseI-0.647*noiseQ,
    noiseY-1.106*noiseI+1.703*noiseQ
  );
  color+=noiseYiq*uNoiseWeight;
  float sparkleMask=step(0.995,hash(noiseCell+vec2(97.0,3.0)));
  float sparkleI=(hash(noiseCell+5.0)-0.5)*2.0;
  float sparkleQ=(hash(noiseCell+9.0)-0.5)*2.0;
  vec3 sparkleYiq=0.5+0.5*vec3(
    0.956*sparkleI+0.621*sparkleQ,
    -0.272*sparkleI-0.647*sparkleQ,
    -1.106*sparkleI+1.703*sparkleQ
  );
  color+=sparkleYiq*sparkleMask*0.3*uNoiseWeight;
  float distortMask=step(0.997,hash(noiseCell+vec2(43.0,61.0)));
  vec2 distortOffset=
    vec2(hash(noiseCell+1.0)-0.5,hash(noiseCell+2.0)-0.5)*0.01;
  vec3 distortColor=texture(uScene,clamp(uv+distortOffset,0.0,1.0)).rgb;
  color=mix(color,distortColor,distortMask*0.5*uNoiseWeight);

  // Head-switch band: a thin strip near the bottom of frame (where a real
  // VCR's playback head crosses the tape edge) gets a stronger tear,
  // fading smoothly over the band's height rather than a hard cutoff.
  float headSwitchBand=smoothstep(0.06,0.0,abs(scanline-0.98));
  float headSwitchJitter=(hash(vec2(uTime*30.0,scanline))-0.5)*0.06;
  vec2 headSwitchUv=vec2(
    clamp(uv.x+headSwitchJitter*uHeadSwitchWeight*headSwitchBand,0.0,1.0),
    uv.y
  );
  vec3 headSwitchColor=texture(uScene,headSwitchUv).rgb;
  color=mix(color,headSwitchColor,uHeadSwitchWeight*headSwitchBand);

  // Dropout: sparse, per-scanline streaks mimicking analog tape dropout.
  // Real dropout is neither a flat full-width bar nor a fixed brightness —
  // a per-x noise mask (smoothstepped, not a hard cutoff) makes each
  // streak's width and edges vary along its length, and a per-streak
  // random intensity keeps consecutive dropouts from looking identical. A
  // slow ~6Hz reroll (not per-frame) and a high activation threshold keep
  // this an occasional glitch rather than a strobe — subtle enough not to
  // distract during continuous play, even at uDropoutWeight's full value.
  float dropoutCell=floor(uTime*6.0);
  float dropoutRoll=hash(vec2(floor(scanline*216.0),dropoutCell));
  float dropoutActive=step(0.994,dropoutRoll);
  float dropoutIntensity=hash(vec2(dropoutCell,17.0))*0.5+0.4;
  float dropoutMask=hash(
    vec2(floor(uv.x*48.0),floor(scanline*216.0)+dropoutCell*3.0)
  );
  float dropoutStripe=
    dropoutActive*uDropoutWeight*smoothstep(0.3,0.9,dropoutMask);
  color=mix(color,vec3(dropoutIntensity),dropoutStripe*0.8);

  // Ghosting: blends in last frame's own VHS *output* (uHistory, never
  // uScene), horizontally offset, for a trailing double-image echo —
  // reading the previous frame's already-composited result is what makes
  // this a genuine feedback trail rather than a static double-exposure.
  vec2 ghostUv=vec2(clamp(uv.x-0.015,0.0,1.0),uv.y);
  vec3 ghostColor=texture(uHistory,ghostUv).rgb;
  color=mix(color,ghostColor,uGhostWeight*0.5);

  oColor=vec4(clamp(color,0.0,1.0),1.0);
}
''';

const String volumetricLightFragSrc = '''
#version 300 es
precision highp float;

in vec2 vUv;
layout(location = 0) out vec4 oColor;

uniform sampler2D uSceneDepth;
uniform float uNear;
uniform float uFar;
uniform mat4 uViewProjection;
uniform vec3 uLightDir;
uniform vec3 uLightColor;
uniform float uShaftIntensity;
uniform float uFogDensity;
uniform float uAnisotropy;
uniform mat4 uView;
uniform mat4 uInverseProjection;
uniform vec3 uVolumetricAlbedo;
uniform float uVolumetricHeightFalloff;
uniform float uVolumetricDustDensity;
uniform float uVolumetricJitter;
uniform float uVolumetricIntensity;
uniform float uVolumetricSampleCount;
uniform float uVolumetricSourceCount;

uniform vec3 uSourcePosition0;
uniform vec3 uSourceColor0;
uniform float uSourceIntensity0;
uniform float uSourceReferenceDistance0;
uniform float uSourceCutoffDistance0;
uniform vec3 uSourcePosition1;
uniform vec3 uSourceColor1;
uniform float uSourceIntensity1;
uniform float uSourceReferenceDistance1;
uniform float uSourceCutoffDistance1;
uniform vec3 uSourcePosition2;
uniform vec3 uSourceColor2;
uniform float uSourceIntensity2;
uniform float uSourceReferenceDistance2;
uniform float uSourceCutoffDistance2;
uniform vec3 uSourcePosition3;
uniform vec3 uSourceColor3;
uniform float uSourceIntensity3;
uniform float uSourceReferenceDistance3;
uniform float uSourceCutoffDistance3;

float linearDepth(float depth) {
  float z = depth * 2.0 - 1.0;
  return (2.0 * uNear * uFar) / max(uFar + uNear - z * (uFar - uNear), 1e-4);
}

float phaseHenyeyGreenstein(float cosTheta, float anisotropy) {
  float g = clamp(anisotropy, -0.85, 0.85);
  float denominator = 1.0 + g * g - 2.0 * g * cosTheta;
  return (1.0 - g * g) / (12.5663706 * pow(max(denominator, 1e-3), 1.5));
}

vec3 sourceContribution(
  vec3 position,
  vec3 color,
  float intensity,
  float referenceDistance,
  float cutoffDistance,
  vec3 viewRay,
  float rayLength
) {
  vec4 clip = uViewProjection * vec4(position, 1.0);
  if (clip.w <= 0.0) return vec3(0.0);
  vec3 sourceView = (uView * vec4(position, 1.0)).xyz;
  float sourceDistance = length(sourceView);
  float tClosest = clamp(dot(sourceView, viewRay), 0.0, rayLength);
  vec3 sampleToSource = sourceView - viewRay * tClosest;
  float distanceToSource = max(length(sampleToSource), 1e-3);
  float cutoff = 1.0 - smoothstep(
    cutoffDistance * 0.65, cutoffDistance, sourceDistance);
  float inverseSquare = intensity * referenceDistance * referenceDistance /
      max(distanceToSource * distanceToSource,
          referenceDistance * referenceDistance);
  // The incoming direction is source -> sample and the outgoing direction is
  // sample -> camera. This is the same phase convention as the directional
  // medium path, but now evaluated against the located source.
  float phase = phaseHenyeyGreenstein(
    dot(normalize(sampleToSource), viewRay), uAnisotropy);
  // Located practicals and lightning must also acquire visible body in a
  // dust-filled room. Use the same broad haze plus particulate density as the
  // directional march; otherwise a clear-air fog toggle would accidentally
  // erase dust-lit source rays while the directional shafts still showed it.
  float mediumDensity = max(uFogDensity + uVolumetricDustDensity, 0.0);
  float mediumWeight = 1.0 - exp(-max(
    mediumDensity * min(rayLength, cutoffDistance), 0.0));
  float pathWeight = clamp(
    rayLength / max(sourceDistance, referenceDistance), 0.0, 1.0);
  return color * inverseSquare * phase * cutoff * mediumWeight * pathWeight *
    uVolumetricIntensity * 0.35;
}

void main() {
  float depth = texture(uSceneDepth, vUv).r;
  vec4 viewPoint = uInverseProjection * vec4(vUv * 2.0 - 1.0, -1.0, 1.0);
  viewPoint /= max(abs(viewPoint.w), 1e-5);
  vec3 viewRay = normalize(viewPoint.xyz);
  // linearDepth is camera-space Z; convert it to distance along the actual
  // reconstructed ray so wide and tall projections integrate equally.
  float cameraDepth = linearDepth(depth);
  float rayLength = min(cameraDepth / max(-viewRay.z, 1e-3), uFar);
  float density = max(uFogDensity, 0.0);

  // A fixed, bounded integral keeps the pass deterministic and makes its
  // cost predictable on weak adapters. The depth buffer stops integration at
  // the first opaque surface, so shafts do not leak through geometry.
  const int maxSampleCount = 24;
  int sampleCount = int(clamp(uVolumetricSampleCount, 4.0, 24.0));
  vec3 scatter = vec3(0.0);
  float transmittance = 1.0;
  float stepLength = rayLength / float(sampleCount);
  float jitterSeed = fract(sin(dot(vUv, vec2(127.1, 311.7))) * 43758.5453);
  float jitter = (jitterSeed - 0.5) * clamp(uVolumetricJitter, 0.0, 0.5);
  for (int i = 0; i < maxSampleCount; i++) {
    if (i >= sampleCount) break;
    float distanceAlongRay = clamp(
      (float(i) + 0.5 + jitter) * stepLength, 0.0, rayLength);
    float heightWeight = exp(-max(distanceAlongRay * uVolumetricHeightFalloff, 0.0));
    // Dust is a separate, host-resolved particulate phase. It is denser near
    // the occupied room volume than the broad atmospheric haze, so shafts gain
    // visible body without turning the far horizon opaque. At zero density the
    // extra term is exactly zero and the established fog path is unchanged.
    float dustWeight = exp(-max(distanceAlongRay *
      uVolumetricHeightFalloff * 0.45, 0.0));
    float opticalDensity = density +
      max(uVolumetricDustDensity, 0.0) * dustWeight;
    float opticalDepth = opticalDensity * stepLength * heightWeight;
    float sampleTransmittance = exp(-opticalDepth);
    float phase = phaseHenyeyGreenstein(dot(normalize(-uLightDir), viewRay), uAnisotropy);
    scatter += transmittance * (uLightColor * uVolumetricAlbedo *
      uShaftIntensity * uVolumetricIntensity * phase) * opticalDepth;
    transmittance *= sampleTransmittance;
  }

  if (uVolumetricSourceCount > 0.5) {
    scatter += sourceContribution(
      uSourcePosition0, uSourceColor0, uSourceIntensity0,
      uSourceReferenceDistance0, uSourceCutoffDistance0, viewRay, rayLength);
  }
  if (uVolumetricSourceCount > 1.5) {
    scatter += sourceContribution(
      uSourcePosition1, uSourceColor1, uSourceIntensity1,
      uSourceReferenceDistance1, uSourceCutoffDistance1, viewRay, rayLength);
  }
  if (uVolumetricSourceCount > 2.5) {
    scatter += sourceContribution(
      uSourcePosition2, uSourceColor2, uSourceIntensity2,
      uSourceReferenceDistance2, uSourceCutoffDistance2, viewRay, rayLength);
  }
  if (uVolumetricSourceCount > 3.5) {
    scatter += sourceContribution(
      uSourcePosition3, uSourceColor3, uSourceIntensity3,
      uSourceReferenceDistance3, uSourceCutoffDistance3, viewRay, rayLength);
  }

  // Fade the final sample at the far plane and keep the additive output
  // bounded so a storm flash cannot blow out the entire frame.
  float farFade = 1.0 - smoothstep(uFar * 0.75, uFar, rayLength);
  oColor = vec4(min(scatter * farFade, vec3(8.0)), 1.0);
}
''';

const String volumetricCompositeFragSrc = '''
#version 300 es
precision highp float;

in vec2 vUv;
layout(location = 0) out vec4 oColor;
uniform sampler2D uVolumetric;
uniform float uVolumetricStrength;

void main() {
  vec3 light = texture(uVolumetric, vUv).rgb;
  oColor = vec4(light * max(uVolumetricStrength, 0.0), 1.0);
}
''';
